// The Algorithms knowledge-graph model (#2761/#2958): the impl-only, primitives-rooted model — seed
// integrity, the per-language kits, the composes graph, and the compose-depth layout. The abstract
// concept ontology (nodes/edges) was removed with #2961 — a node IS its implementation.
import { describe, it, expect } from "vitest";
import {
  KNOWLEDGE, TECHS, implById, usedByImpl, buildKnowledge,
  kitTechs, kitImpls, kitImplsByRole, kitGraph, groupImplsByLanguage, layoutKitGraph,
  matchesImpl, type AlgoImpl, type RawKnowledge,
} from "@/features/algorithms/lib/knowledge";

describe("KNOWLEDGE seed (impl-only, #2958)", () => {
  it("carries the Rust kit — unique ids, known roles, real same-tech composes", () => {
    const impls = KNOWLEDGE.implementations;
    expect(impls.length).toBeGreaterThanOrEqual(16);
    const ids = new Set(impls.map((i) => i.id));
    expect(ids.size).toBe(impls.length); // ids unique
    for (const im of impls) {
      expect(["primitive", "algorithm"]).toContain(im.role);
      expect(TECHS).toContain(im.tech);
      expect(im.name.trim().length).toBeGreaterThan(0);
      // #2972: an algorithm carries real, reusable code; a primitive is a DESCRIPTOR of a language
      // built-in — it names its std `ref` and is NOT re-coded.
      if (im.role === "algorithm") {
        expect((im.code ?? "").trim().length).toBeGreaterThan(0);
      } else {
        expect((im.ref ?? "").trim().length).toBeGreaterThan(0);
        expect(im.code).toBeUndefined();
      }
      for (const c of im.composes) {
        expect(ids.has(c)).toBe(true); // every composes id is a REAL impl
        expect(implById(KNOWLEDGE, c)!.tech).toBe(im.tech); // and of the SAME tech
      }
    }
  });

  it("is primitives-rooted — every kit has a primitive base and algorithms that compose down to it", () => {
    for (const tech of kitTechs(KNOWLEDGE)) {
      const prims = kitImplsByRole(KNOWLEDGE, tech, "primitive");
      const algos = kitImplsByRole(KNOWLEDGE, tech, "algorithm");
      expect(prims.length).toBeGreaterThan(0); // a base exists
      // At least one algorithm composes a primitive (roots in the base).
      expect(algos.some((a) => a.composes.some((c) => prims.some((p) => p.id === c)))).toBe(true);
    }
  });
});

describe("implById / usedByImpl", () => {
  it("implById resolves an id and misses cleanly", () => {
    expect(implById(KNOWLEDGE, "bfs.rs")?.tech).toBe("rust");
    expect(implById(KNOWLEDGE, "nope.rs")).toBeUndefined();
  });

  it("merge-sort.rs composes merge.rs and roots in the Rust primitives", () => {
    const ms = implById(KNOWLEDGE, "merge-sort.rs");
    expect(ms?.composes).toEqual(["merge.rs", "rust.vec", "rust.slice"]);
  });

  it("usedByImpl is the reverse of composes", () => {
    // merge.rs is composed only by merge-sort.rs.
    expect(usedByImpl(KNOWLEDGE, "merge.rs").map((i) => i.id)).toEqual(["merge-sort.rs"]);
    // A top-level algorithm no one composes has no reverse edges.
    expect(usedByImpl(KNOWLEDGE, "merge-sort.rs")).toEqual([]);
    // A language primitive is composed UP by its algorithms.
    expect(usedByImpl(KNOWLEDGE, "rust.iterator").map((i) => i.id)).toContain("quick-sort.rs");
  });
});

describe("language kits (#2863) — a kit is every impl of one tech, grouped by role", () => {
  it("kitTechs lists the seeded languages, TECHS-ordered", () => {
    // Rust-first, plus a minimal TypeScript kit seeded for the #3116 Component→Algorithm example
    // (typescript.number + fibonacci.ts); TECHS order puts typescript first.
    expect(kitTechs(KNOWLEDGE)).toEqual(["typescript", "rust"]);
  });

  it("kitImpls scopes to one language; kitImplsByRole splits primitives (language built-ins) from algorithms", () => {
    const rs = kitImpls(KNOWLEDGE, "rust");
    expect(rs.length).toBeGreaterThan(0);
    expect(rs.every((im) => im.tech === "rust")).toBe(true);
    const prims = kitImplsByRole(KNOWLEDGE, "rust", "primitive");
    const algos = kitImplsByRole(KNOWLEDGE, "rust", "algorithm");
    expect(prims.map((im) => im.id)).toContain("rust.iterator"); // a language primitive
    expect(prims.map((im) => im.id)).toContain("rust.vec"); // a language primitive
    expect(algos.map((im) => im.id)).toContain("merge.rs"); // a user impl
    expect(algos.map((im) => im.id)).toContain("merge-sort.rs"); // an algorithm
    expect(prims.length + algos.length).toBe(rs.length);
  });

  it("groupImplsByLanguage makes one folder per language, primitives before algorithms (the rail tree)", () => {
    const groups = groupImplsByLanguage(KNOWLEDGE);
    expect(groups.map((g) => g.tech)).toEqual(kitTechs(KNOWLEDGE));
    const rs = groups.find((g) => g.tech === "rust")!;
    expect(rs.label).toBe("Rust");
    expect(rs.key).toBe("lang:rust");
    expect(rs.dot).toBe("var(--state-wait)"); // the per-language folder-head color (#2902)
    expect(rs.impls.every((im) => im.tech === "rust")).toBe(true);
    const firstAlgo = rs.impls.findIndex((im) => im.role === "algorithm");
    const lastPrim = rs.impls.map((im) => im.role).lastIndexOf("primitive");
    expect(lastPrim).toBeLessThan(firstAlgo);
    expect(rs.impls.map((im) => im.id)).toContain("rust.iterator"); // a primitive
    expect(rs.impls.map((im) => im.id)).toContain("merge-sort.rs"); // an algorithm
  });

  it("kitGraph builds a kit's own impl graph — nodes are that tech's impls, wired by composes only", () => {
    const kg = kitGraph(KNOWLEDGE, "rust");
    expect(kg.nodes).toEqual(kitImpls(KNOWLEDGE, "rust"));
    expect(kg.nodes.every((n) => n.tech === "rust")).toBe(true);
    // The builds-on edge (merge-sort.rs composes merge.rs)…
    expect(kg.edges).toContainEqual({ from: "merge-sort.rs", to: "merge.rs", rel: "composes" });
    // …and an algorithm rooting in a language primitive (quick-sort.rs composes rust.iterator).
    expect(kg.edges).toContainEqual({ from: "quick-sort.rs", to: "rust.iterator", rel: "composes" });
    // Every edge is a `composes` between in-kit impl ids (the ontology is gone, #2961).
    const ids = new Set(kg.nodes.map((n) => n.id));
    expect(kg.edges.every((e) => e.rel === "composes" && ids.has(e.from) && ids.has(e.to))).toBe(true);
    // The composes edge count equals the sum of in-kit composes references.
    const composeRefs = kg.nodes.reduce((acc, n) => acc + n.composes.filter((c) => ids.has(c)).length, 0);
    expect(kg.edges.length).toBe(composeRefs);
  });

  it("layoutKitGraph bands by origin and keeps depth as the order INSIDE a cluster", () => {
    const kg = kitGraph(KNOWLEDGE, "rust");
    const l = layoutKitGraph(kg);
    expect([...l.pos.keys()].sort()).toEqual(kg.nodes.map((n) => n.id).sort());

    // DEPTH IS NO LONGER THE GLOBAL X AXIS, and that is the change. It was, and it is what produced a
    // 3,308 x 43,114 world on the typescript kit: 538 of 644 nodes share depth 1, so ONE column held 84%
    // of the graph and ran 52 screens down. ORIGIN is the coarse axis now, so `rust.vec` (a language
    // built-in) and `merge.rs` (a reference algorithm) are not comparable by x at all — different bands.
    const bandOf = (id: string) => {
      const p = l.pos.get(id)!;
      return l.clusters.find((c) => p.x >= c.x && p.x < c.x + c.w && p.y >= c.y && p.y < c.y + c.h)!;
    };
    expect(bandOf("rust.vec").origin).toBe("built-ins");
    expect(bandOf("merge.rs").origin).toBe("reference");

    // Depth survives LOCALLY: inside one cluster, base still precedes what builds on it.
    if (bandOf("merge.rs").label === bandOf("merge-sort.rs").label) {
      const a = l.pos.get("merge.rs")!, b = l.pos.get("merge-sort.rs")!;
      expect(a.y < b.y || (a.y === b.y && a.x < b.x)).toBe(true);
    }

    expect(l.world.w).toBeGreaterThan(0);
    expect(l.world.h).toBeGreaterThan(0);
    expect(l.world.h / l.world.w).toBeLessThan(5); // never a runaway column again
  });
});

describe("matchesImpl — the rail's one filter (#4128)", () => {
  const im = (o: Partial<AlgoImpl> & Pick<AlgoImpl, "id" | "tech">): AlgoImpl =>
    ({ role: "algorithm", name: o.id, composes: [], ...o });

  it("matches name, id, FOLDER PATH and tags — so a folder can be narrowed to by typing it", () => {
    // The folder half is the point: the components rail's `matchesQuery` has matched the folder path
    // since #3589, and with the domain dropdown gone (#4128) search is how this rail narrows too.
    const dijkstra = im({ id: "dijkstra.rs", tech: "rust", name: "dijkstra", folder: "graphs/shortest-path", tags: ["greedy"] });
    expect(matchesImpl(dijkstra, "dijk")).toBe(true);       // name
    expect(matchesImpl(dijkstra, ".rs")).toBe(true);         // id
    expect(matchesImpl(dijkstra, "shortest-path")).toBe(true); // folder path
    expect(matchesImpl(dijkstra, "graphs/")).toBe(true);       // a partial path
    expect(matchesImpl(dijkstra, "greedy")).toBe(true);        // tag
    expect(matchesImpl(dijkstra, "quicksort")).toBe(false);
  });

  it("is case-insensitive, and an empty query matches everything", () => {
    const plain = im({ id: "plain.rs", tech: "rust", name: "Plain" });
    expect(matchesImpl(plain, "PLAIN")).toBe(true);
    expect(matchesImpl(plain, "")).toBe(true);
    expect(matchesImpl(plain, "   ")).toBe(true);
  });

  it("never crashes on an impl carrying neither folder nor tags (the seeded classics)", () => {
    const seeded = im({ id: "merge-sort.rs", tech: "rust", name: "merge sort" });
    expect(matchesImpl(seeded, "merge")).toBe(true);
    expect(matchesImpl(seeded, "shared/ui")).toBe(false);
  });
});

describe("the domain facet is no longer an organizer (#4128)", () => {
  it("keeps `domain` on the RECORD — the CLI still writes and filters it — while the rail ignores it", () => {
    // #4128 removed the rail's domain dropdown and with it `domainsOf`/`implsByDomain`/`kitImplsByDomain`,
    // which had no other consumer. The FIELD stays: `bsc graph impl set --domain` / `impl list --domain`
    // still read it, and the harvest still derives one. What is gone is domain as a way the library is
    // presented — the folder tree (a strictly richer derivation of the same `src`) is that.
    const tagged = KNOWLEDGE.implementations.find((i) => i.domain);
    expect(tagged?.domain).toBeTruthy();
  });

  describe("a record missing `composes` must not take the hydrate down", () => {
    // THE OUTAGE THIS EXISTS FOR. `bsc-bluetooth--tests.rs` landed in the writable store with no
    // `composes`. `AlgoImpl` declares the field required, so every consumer reaches for it unguarded —
    // `graphSig` does `.join(",")` — and that threw inside the hydrate poll. `setGraph` never ran and
    // `useKnowledgeGraph` kept the packaged seed, so the page showed 758 records instead of 1,403 and
    // said nothing. A missing optional field may cost one record's edges; it may not cost the hydrate.
    it("defaults it to an empty array so the type's promise holds", () => {
      const g = buildKnowledge({ implementations: [{ id: "a.rs", name: "a" }] } as unknown as RawKnowledge);
      expect(g.implementations[0].composes).toEqual([]);
      // …and the shape every consumer relies on actually works:
      expect(() => g.implementations.map((im) => im.composes.join(","))).not.toThrow();
    });

    it("leaves a real `composes` untouched", () => {
      const g = buildKnowledge({
        implementations: [{ id: "a.rs", name: "a", composes: ["b.rs"] }],
      } as unknown as RawKnowledge);
      expect(g.implementations[0].composes).toEqual(["b.rs"]);
    });

    it("normalises a `composes` that is present but not an array", () => {
      const g = buildKnowledge({
        implementations: [{ id: "a.rs", name: "a", composes: null }],
      } as unknown as RawKnowledge);
      expect(g.implementations[0].composes).toEqual([]);
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  KNOWLEDGE, kitGraph, layoutKitGraph, originOf, clusterOf, NODE_H,
  type AlgoImpl, type KitGraph,
} from "@/features/algorithms/lib/knowledge";

/** A node with just the fields the layout reads. */
const impl = (id: string, over: Partial<AlgoImpl> = {}): AlgoImpl => ({
  id, tech: "typescript", role: "algorithm", name: id, composes: [], ...over,
});
const kit = (nodes: AlgoImpl[]): KitGraph => ({ nodes, edges: [] });

describe("origin banding", () => {
  it("separates crate code from frontend code — the split the crate migration needs", () => {
    expect(originOf(impl("a", { src: "crates/bsc-shot/src/lib.rs" }))).toBe("crates");
    expect(originOf(impl("b", { src: "src-tauri/src/session/launch.rs" }))).toBe("backend");
    expect(originOf(impl("c", { src: "src/features/glance/lib/x.ts" }))).toBe("features");
    expect(originOf(impl("d", { src: "src/shared/lib/core/y.ts" }))).toBe("shared");
    expect(originOf(impl("e", { src: "src/app/console/z.ts" }))).toBe("shell");
    expect(originOf(impl("f", { src: "src/store/slices/s.ts" }))).toBe("store");
  });

  /** The textbook algorithms (a-star.rs, bfs.rs) carry no `src` and are NOT codebase code — they are a
   *  third population that should not mix into either the crates or the frontend. */
  it("keeps reference algorithms and language built-ins out of the codebase bands", () => {
    expect(originOf(impl("a-star.rs", { src: undefined }))).toBe("reference");
    expect(originOf(impl("rust.vec", { role: "primitive" }))).toBe("built-ins");
  });

  it("clusters by the crate, the feature, or the folder — what the rail already navigates by", () => {
    expect(clusterOf(impl("a", { src: "crates/bsc-shot/src/lib.rs" }))).toBe("bsc-shot");
    expect(clusterOf(impl("b", { src: "src/features/planner/lib/x.ts" }))).toBe("planner");
    expect(clusterOf(impl("c", { src: "src/shared/lib/core/y.ts", folder: "shared/lib/core" }))).toBe("shared/lib/core");
    expect(clusterOf(impl("d", {}))).toBe("general");
  });
});

describe("layoutKitGraph", () => {
  /**
   * THE REGRESSION THIS EXISTS FOR. The old layout put a node in the column of its compose depth and
   * stacked with no wrap; 538 of 644 typescript nodes are depth 1, so one column ran 43,114px down —
   * 52 screens of travel to reach a node. Asserted against the REAL packaged graph, because a synthetic
   * fixture cannot reproduce the depth-1 pile-up that caused it.
   */
  it("keeps the real typescript kit to a screen-shaped world, not a 43,000px column", () => {
    const laid = layoutKitGraph(kitGraph(KNOWLEDGE, "typescript"));
    expect(laid.pos.size).toBeGreaterThan(100);
    expect(laid.world.h).toBeLessThan(12_000);
    // Aspect, not just height: wrapping the depths alone was measured at 8,280px WIDE, which is the
    // same problem rotated. Neither side may run away from the other.
    const aspect = laid.world.h / laid.world.w;
    expect(aspect).toBeGreaterThan(0.2);
    expect(aspect).toBeLessThan(5);
  });

  it("gives every node a position, and never two nodes the same one", () => {
    const laid = layoutKitGraph(kitGraph(KNOWLEDGE, "typescript"));
    const seen = new Set([...laid.pos.values()].map((p) => `${p.x},${p.y}`));
    expect(seen.size).toBe(laid.pos.size);
  });

  it("is pure — the same graph lays out identically twice", () => {
    const g = kitGraph(KNOWLEDGE, "typescript");
    const a = layoutKitGraph(g);
    const b = layoutKitGraph(g);
    expect([...b.pos].map(([k, v]) => [k, v.x, v.y])).toEqual([...a.pos].map(([k, v]) => [k, v.x, v.y]));
  });

  it("bands are laid out in ORIGIN_BANDS order, each below the last", () => {
    const laid = layoutKitGraph(kit([
      impl("c1", { src: "crates/bsc-shot/src/lib.rs" }),
      impl("f1", { src: "src/features/glance/a.ts" }),
      impl("r1", {}),
    ]));
    const band = (o: string) => laid.clusters.find((c) => c.origin === o)!;
    expect(band("crates").y).toBeLessThan(band("features").y);
    expect(band("features").y).toBeLessThan(band("reference").y);
  });

  /** Depth is no longer the global axis, but base-to-derived must still read INSIDE a cluster. */
  it("orders a cluster by compose depth, shallowest first", () => {
    const nodes = [
      impl("deep.ts", { src: "src/shared/x/deep.ts", folder: "f", composes: ["mid.ts"] }),
      impl("mid.ts", { src: "src/shared/x/mid.ts", folder: "f", composes: ["base.ts"] }),
      impl("base.ts", { src: "src/shared/x/base.ts", folder: "f" }),
    ];
    const laid = layoutKitGraph(kit(nodes));
    const y = (id: string) => laid.pos.get(id)!.y;
    const x = (id: string) => laid.pos.get(id)!.x;
    // One column at this size, so "earlier" is "higher".
    expect(y("base.ts")).toBeLessThanOrEqual(y("mid.ts"));
    expect(y("mid.ts")).toBeLessThanOrEqual(y("deep.ts"));
    expect(new Set([x("base.ts"), x("mid.ts"), x("deep.ts")]).size).toBe(1);
  });

  it("an empty kit is a degenerate world rather than a crash", () => {
    const laid = layoutKitGraph(kit([]));
    expect(laid.pos.size).toBe(0);
    expect(laid.world.w).toBeGreaterThan(0);
    expect(laid.world.h).toBeGreaterThan(0);
    expect(laid.clusters).toEqual([]);
  });

  it("a single node still gets a real box", () => {
    const laid = layoutKitGraph(kit([impl("only.ts", { src: "src/shared/a/only.ts", folder: "a" })]));
    expect(laid.pos.size).toBe(1);
    expect(laid.world.h).toBeGreaterThan(NODE_H);
    expect(laid.clusters).toHaveLength(1);
    expect(laid.clusters[0].count).toBe(1);
  });
});

// THE TAB IS A LENS, NOT A PARTITION (`the-tab-is-a-lens-not-a-partition`).
//
// Selecting a language tab must change FOCUS — which nodes are laid out — and never which edges exist.
// The distinction is not decorative. Technology is a CURATION scope: `studioScopeDirective` splits the
// librarian per language so each curates its own partition, and that governs who may WRITE a record. It
// says nothing about what may REFERENCE one. The cross-graph URN grammar makes that concrete —
// `@bsc/algorithms/fibonacci` is kit-less, so a React component resolves a TypeScript implementation
// across both pillar AND technology (epic #3114, whose whole purpose was ending exactly that siloing).
//
// WHY THIS IS A GUARD AND NOT A FIX: measured against the seed today there are 578 within-language
// `composes` edges and ZERO that cross a language, so nothing is being dropped right now. `kitGraph`
// filters edges to targets inside the same language (`if (ids.has(c))`), which means the day someone
// adds a cross-language edge it will vanish from the view with no error and no warning — just a link
// that is not drawn. That is the failure this file exists to make loud, and it cannot be caught by
// eye: a missing edge looks exactly like an edge that was never authored.
import { describe, it, expect } from "vitest";
import { KNOWLEDGE, kitTechs, kitGraph, buildKnowledge, type AlgoImpl } from "@/features/algorithms/lib/knowledge";

/** Every `composes` edge in the graph whose target actually resolves, as `from->to`. */
const allResolvableEdges = (g: typeof KNOWLEDGE): Set<string> => {
  const ids = new Set(g.implementations.map((i) => i.id));
  const out = new Set<string>();
  for (const im of g.implementations) {
    for (const c of im.composes) if (ids.has(c)) out.add(`${im.id}->${c}`);
  }
  return out;
};

/** Every edge the UI actually renders, unioned across every tab a user can select. */
const renderedAcrossAllTabs = (g: typeof KNOWLEDGE): Set<string> => {
  const out = new Set<string>();
  for (const tech of kitTechs(g)) {
    for (const e of kitGraph(g, tech).edges) out.add(`${e.from}->${e.to}`);
  }
  return out;
};

describe("the language tab is a lens over the algorithms graph", () => {
  it("renders EVERY edge the store holds across the set of tabs — none is dropped", () => {
    // The property, stated directly: no tab selection may hide an edge from the graph entirely.
    const stored = allResolvableEdges(KNOWLEDGE);
    const rendered = renderedAcrossAllTabs(KNOWLEDGE);
    const missing = [...stored].filter((e) => !rendered.has(e));
    expect(
      missing,
      `${missing.length} edge(s) exist in the store but are drawn under NO tab — ` +
      `kitGraph drops any \`composes\` whose target is in another language. ` +
      `The tab must be a lens, not a partition: ${missing.slice(0, 5).join(", ")}`,
    ).toEqual([]);
    expect(stored.size).toBeGreaterThan(0); // the check is meaningless against an empty graph
  });

  it("FAILS LOUDLY for a graph that does have a cross-language edge — the guard actually guards", () => {
    // Proving the assertion above can fail. Without this, a tautology (an empty `missing` because
    // nothing is ever compared) would read exactly like a passing guard — which is the failure mode
    // this repo keeps getting caught by: a green check that sees less than the reader assumes.
    const im = (o: Partial<AlgoImpl> & Pick<AlgoImpl, "id" | "tech" | "name">): AlgoImpl =>
      ({ role: "algorithm", composes: [], ...o });
    const crossing = buildKnowledge({
      implementations: [
        im({ id: "caller.ts", tech: "typescript", name: "caller", composes: ["helper.rs"] }),
        im({ id: "helper.rs", tech: "rust", name: "helper" }),
      ],
    });
    expect(allResolvableEdges(crossing).has("caller.ts->helper.rs")).toBe(true);
    expect(
      renderedAcrossAllTabs(crossing).has("caller.ts->helper.rs"),
      "kitGraph drops a cross-language edge — this is the case the guard above is watching for",
    ).toBe(false);
  });

  it("gives each tab its own nodes, and every node exactly one tab", () => {
    // The other half of "focus, not partition": focus must be TOTAL and UNAMBIGUOUS. A node reachable
    // from no tab is unreachable in the UI; a node on two tabs is two copies of one record.
    const seen = new Map<string, number>();
    for (const tech of kitTechs(KNOWLEDGE)) {
      for (const n of kitGraph(KNOWLEDGE, tech).nodes) seen.set(n.id, (seen.get(n.id) ?? 0) + 1);
    }
    const unreachable = KNOWLEDGE.implementations.filter((i) => !seen.has(i.id)).map((i) => i.id);
    const duplicated = [...seen].filter(([, n]) => n > 1).map(([id]) => id);
    expect(unreachable, "impls reachable from no tab").toEqual([]);
    expect(duplicated, "impls appearing under more than one tab").toEqual([]);
  });
});

