// The Algorithms knowledge graph — pure model (#2761, epic #2760). React/Tauri-free so the tests, the
// page render, and the harvest lift all share ONE model. PRIMITIVES-ROOTED, impl-is-concept
// (#2958/#2961): each language kit is a graph of its implementations, rooted in that language's
// PRIMITIVES (Vec, Iterator, …) with algorithms composing UP from them. There is NO abstract concept
// layer — a node IS a concrete implementation. Loaded from the packaged seed
// (@data/knowledge/algorithms.json — the SAME source `bsc graph` embeds).
import { buildFolderTree, folderItemCount, type FolderNode } from "@/shared/lib/core/folderTree";
import RAW from "@data/knowledge/algorithms.json";

/** The languages a kit can be in (#2770). */
export type Tech = "typescript" | "rust";

/** The implementation techs, in display order. */
export const TECHS: Tech[] = ["typescript", "rust"];

/** Per-tech display label + file extension (an algorithm impl's id suffix) + rail dot color (a
 *  per-language identifier, the Algorithms analog of a Designs kit's `dot`). */
export const TECH_META: Record<Tech, { label: string; ext: string; dot: string }> = {
  typescript: { label: "TypeScript", ext: "ts", dot: "var(--info)" },
  rust: { label: "Rust", ext: "rs", dot: "var(--state-wait)" },
};

/** What KIND of thing a record is (#2863/#2958): a `primitive` is a LANGUAGE built-in
 *  (`rust.iterator`, `rust.vec`); an `algorithm` composes primitives + simpler algorithms up — the
 *  "base vs growing" distinction the rail groups by; a `test` is a module whose whole purpose is to
 *  check other records (`a-test-only-module-is-not-an-algorithm`).
 *
 *  A record is a `test` when its DECLARATION gates it out of production builds — `#[cfg(test)]` on the
 *  `mod` line — never because of its filename. The Rust mirror of this contract is `ROLES` in
 *  `crates/bsc-graph/src/lib.rs`, and the two must widen together: the store is untyped JSON, so a
 *  union narrower than the store holds is not a compile error here, it is a silent untruth. */
export type ImplRole = "primitive" | "algorithm" | "test";

/**
 * A unit of a language kit (#2863/#2958) — a node in one `tech`. The implementation IS the concept:
 * there is no abstract concept node. `role` splits **primitives** — a language BUILT-IN (`rust.vec`,
 * `rust.iterator`) that is DESCRIBED by its std `ref`, never re-coded (#2972) — from **algorithms**:
 * real reusable `code` that `compose`s OTHER impls of the SAME tech, growing UP from the primitive base
 * (e.g. `merge-sort.rs` composes `merge.rs`, `rust.vec`, `rust.slice`). `id` is `<name>.<ext>` for an
 * algorithm, `<tech>.<name>` for a primitive.
 */
/** The manipulation KINDS an algorithm can carry (#3210, epic #3209) — the "what it does" axis of the
 *  animation (`sort`/`search`/…), paired with the DATA STRUCTURE it operates on to pick the live
 *  visualization. Grows as more example animations land (matrix ops, etc.). */
export const ALGO_KINDS = ["sort", "search", "traversal", "accumulate", "transform"] as const;
export type AlgoKind = (typeof ALGO_KINDS)[number];

export interface AlgoImpl {
  /** sha256 of the record's source, set by `graph_dump`'s index projection — the index carries no
   *  bodies, so this is what tells a consumer the source MOVED. Absent on a record with no source, and
   *  absent from the packaged seed, which carries the bodies themselves. */
  codeHash?: string;
  /** `<name>.<ext>` (algorithm) or `<tech>.<name>` (primitive) — e.g. "merge-sort.rs", "rust.iterator". */
  id: string;
  tech: Tech;
  /** What kind of record this is (#2863) — `primitive` (a language built-in), `algorithm` (composed
   *  production logic), or `test` (a module that checks other records). See {@link ImplRole}. */
  role: ImplRole;
  name: string;
  summary?: string;
  /** OTHER implementation ids of the same tech this builds on — the "builds on" edges, pointing DOWN
   *  to the primitive base. */
  composes: string[];
  /** A primitive's std reference — the language built-in it names (`std::vec::Vec`, `i64`). Primitives
   *  are DESCRIBED, not re-coded (#2972); algorithms leave this unset. */
  ref?: string;
  /** An algorithm's real, reusable implementation in `tech`. Optional for a primitive — a language
   *  built-in is described (`ref` + `summary`), not re-coded (#2972). */
  code?: string;
  /** The `@/…` import specifier this impl SATISFIES, set by a module-granularity harvest
   *  (`bsc graph harvest --module`). Present only on impls that are whole MODULES: a function lifted out
   *  of a file satisfies no import, so the field stays absent there rather than null. It is what
   *  `resolveGraphSource` matches on, and the only thing that lets a component's import reach the
   *  algorithms graph at all — components resolve by specifier, algorithms otherwise compose by id. */
  provides?: string;
  /** PROVENANCE (#4091/#4107) — the scanned-root-relative path of the file this was harvested from.
   *  The Rust mirror is `AlgoImpl.src`. Absent on anything authored before it (every seeded impl). */
  src?: string;
  /** The module's TOP-LEVEL MUTABLE BINDINGS — the state it holds, named. Set by a module-granularity
   *  harvest; absent (never `[]`) on a pure module and on any function-granularity impl, which is a
   *  fragment of a file and so holds none of the file's module state.
   *
   *  This is the property that decides whether vendoring the record is equivalent to importing the
   *  module. `provides` makes the loader hand a graph consumer this source INSTEAD of the bundled
   *  module, so a module holding state gives that consumer a SECOND instance of it — a second queue,
   *  a second cache, a second timer — and the two diverge with nothing on screen to say so. Naming the
   *  bindings is what makes that visible rather than something each reader rediscovers in the source. */
  moduleState?: string[];
  /** The FOLDER (#4107) — the nested, `/`-delimited path this impl organizes under, derived from
   *  {@link src} by the SAME derivation components use (`bsc_util::folder_from_src`). Harvest is 1:1:
   *  the folder mirrors where the code actually lives, so the library reads like the tree it came from.
   *  Absent ⇒ the impl is UNFOLDERED and the rail lists it directly under its language. */
  folder?: string;
  /** Optional DOMAIN facet (#3120) — the lightweight, cross-language collection this impl belongs to
   *  (e.g. "logistics", "graphics"). ADDITIVE + backward-compatible: impls authored before the facet
   *  existed have no `domain` and are simply absent from every domain collection, so nothing breaks. A
   *  domain cross-cuts language, so a domain app can pull its relevant subset of the library — all
   *  `logistics` algorithms, across languages. Curated via `bsc graph impl set --domain <d>`. */
  domain?: string;
  /** Optional free-form tags (#3120) — additive keywords for search / cross-cutting collections. Absent
   *  on existing impls; curated via `bsc graph impl set --tags a,b,c`. */
  tags?: string[];
  /** Optional KIND facet (#3210) — the manipulation this algorithm performs (`sort`/`search`/…), the
   *  "what it does" axis that (with its data structure) selects the live animation. ADDITIVE + backward-
   *  compatible: the CREATOR assigns it (`bsc graph impl set --kind sort`), and a heuristic classifier
   *  fills it for untyped impls; absent on impls authored before the facet, so nothing breaks. */
  kind?: AlgoKind;
  /** Optional VIZ-CODE facet (#3218, epic #3215) — the algorithm's VISUALIZATION as data: a JS
   *  trace-program the executor (#3232) runs to DERIVE the animation from the real algorithm. It is a JS
   *  EXPRESSION evaluating to a self-describing descriptor `{ datatype, input, run }` — `datatype` is
   *  `"array" | "matrix" | "graph"` (picks the renderer + input seam), `input` is the default input, and
   *  `run(structure)` is the algorithm written against the matching Traced<Structure> API. The visualizable
   *  form of an impl whose reference `code` can't run in the browser (e.g. Rust). ADDITIVE; the librarian
   *  authors it (`bsc graph impl set --viz-code`). Absent (or malformed) ⇒ the impl falls back to an in-app
   *  trace-program (the sort family / matrix transforms / graph traversals) or shows no animation. */
  vizCode?: string;
}

/** The knowledge model — the per-language implementation tier (#2958); the abstract concept ontology
 *  (nodes/edges) was removed with #2961 (a node IS its implementation). */
export interface KnowledgeGraph {
  implementations: AlgoImpl[];
}

/** The raw graph document shape — `@data/knowledge/algorithms.json` and `bsc graph dump` (#2853). */
export interface RawKnowledge {
  implementations?: AlgoImpl[];
}

/** Build the model from a raw graph document, defaulting missing implementations to []. Shared by the
 *  packaged seed AND the live hydrate from the writable store (#2856), so both produce the identical
 *  model. Pure.
 *
 *  # It NORMALISES `composes`, and that is not defensive padding
 *
 *  `AlgoImpl` declares `composes: string[]` — required — and the store does not guarantee it. This is
 *  the one boundary where raw JSON becomes the typed model, so it is the only place that promise can be
 *  made true; every consumer downstream is written against the type and reaches for the field without a
 *  guard (`graphSig` does `im.composes.join(",")`, `usedByImpl` does `.includes()`, the inspector does
 *  `.map()`).
 *
 *  ONE record arriving without it took the whole page down. `bsc-bluetooth--tests.rs` landed in the
 *  writable store with no `composes`; `graphSig` threw inside the hydrate poll, `setGraph` never ran,
 *  and `useKnowledgeGraph` silently kept the packaged seed — so the Algorithms graph showed 758 records
 *  instead of 1,403 and 36 crate records instead of 542, with no error anywhere a user could see. A
 *  missing optional field should cost one record's edges, never the entire hydrate. */
export function buildKnowledge(raw: RawKnowledge): KnowledgeGraph {
  return {
    implementations: (raw.implementations ?? []).map((im) =>
      Array.isArray(im?.composes) ? im : { ...im, composes: [] },
    ),
  };
}

/** The packaged seed graph — the fast-first-paint fallback + the ONE source `bsc graph` embeds. The live
 *  Algorithms view hydrates from the writable store (`bsc graph dump`, #2856) over this. */
export const KNOWLEDGE: KnowledgeGraph = buildKnowledge(RAW as unknown as RawKnowledge);

// ── The per-tech implementation tier — pure lookups over `graph.implementations`. ──

/** An implementation by its id (e.g. "merge-sort.rs"), or `undefined`. */
export function implById(graph: KnowledgeGraph, id: string): AlgoImpl | undefined {
  return graph.implementations.find((im) => im.id === id);
}

/** The implementations that `compose` `implId` — the reverse of `composes` ("used by"). */
export function usedByImpl(graph: KnowledgeGraph, implId: string): AlgoImpl[] {
  return graph.implementations.filter((im) => im.composes.includes(implId));
}

// ── Language kits (#2863) — a kit is every implementation of one `tech`; navigation groups a kit by
// `role` (primitives → algorithms) the way the Designs rail groups a kit by component role. ──

/** The techs that carry at least one implementation — the language kits present, in {@link TECHS}
 *  order first, then any others in seed order. */
export function kitTechs(graph: KnowledgeGraph): Tech[] {
  const seen = graph.implementations.map((im) => im.tech);
  const ordered = TECHS.filter((t) => seen.includes(t));
  const extras = seen.filter((t, i) => seen.indexOf(t) === i && !ordered.includes(t));
  return [...ordered, ...extras];
}

/** Every implementation in a language kit (all impls of `tech`), in seed order. */
export function kitImpls(graph: KnowledgeGraph, tech: Tech): AlgoImpl[] {
  return graph.implementations.filter((im) => im.tech === tech);
}

/** A kit's implementations of one `role` (its primitives, or its algorithms). */
export function kitImplsByRole(graph: KnowledgeGraph, tech: Tech, role: ImplRole): AlgoImpl[] {
  return graph.implementations.filter((im) => im.tech === tech && im.role === role);
}

// ── The language-folder rail model (#2899) — mirror the Designs rail (kitGroups.ts): each LANGUAGE is a
// folder (like each technology is a folder in Components), its impls the rows. Pure, so the rail render +
// tests share one model. ──

/** A language folder in the Algorithms rail — a `tech` and its implementations (primitives first). */
export interface AlgoLangGroup {
  tech: Tech;
  label: string;
  /** Stable expand-state key (`lang:<tech>`). */
  key: string;
  /** The folder-head color dot — the per-language identifier (#2902), like a Designs kit's `dot`. */
  dot: string;
  /** The kit's impls, primitives before algorithms, each in seed order. */
  impls: AlgoImpl[];
}

/** Group the implementations into one folder per language (#2899) — the rail tree. Languages in
 *  {@link kitTechs} order; within a folder, primitives lead the algorithms (the "base then grows up"
 *  reading). Pure + deterministic. */
export function groupImplsByLanguage(graph: KnowledgeGraph): AlgoLangGroup[] {
  return kitTechs(graph).map((tech) => ({
    tech,
    label: TECH_META[tech]?.label ?? tech,
    key: `lang:${tech}`,
    dot: TECH_META[tech]?.dot ?? "var(--fg-muted)",
    impls: [...kitImplsByRole(graph, tech, "primitive"), ...kitImplsByRole(graph, tech, "algorithm")],
  }));
}

/** One folder of a language's tree — the shared {@link FolderNode} bound to {@link AlgoImpl}. Since
 *  #4128 this is the SAME node the components rail renders, so the two libraries cannot drift apart on
 *  what a folder is. */
export type AlgoFolderNode = FolderNode<AlgoImpl>;

/** Total impls under a folder, transitively — the folder header's count. */
export const folderImplCount = folderItemCount<AlgoImpl>;

/**
 * Partition a language kit's impls into a nested FOLDER TREE by their {@link AlgoImpl.folder} path
 * (#4107) — the algorithms-typed binding of the shared {@link buildFolderTree} (#4128), the same one
 * `groupComponentsByFolder` binds for components.
 *
 * Impls with no folder land in the trailing "ungrouped" bucket rather than spilling flat beside the
 * tree, which is what the components rail has always done — before #4128 this side spilled them, and a
 * mostly-unfoldered library (the seeded classics carry no `src` to derive a folder from) therefore read
 * as a flat list with a few folders wedged on top.
 *
 * Returns `null` when NO impl carries a folder, so a wholly unfoldered kit renders its flat list
 * exactly as it would without folders at all.
 */
export function folderTree(impls: readonly AlgoImpl[]): AlgoFolderNode[] | null {
  return buildFolderTree(impls, (im) => im.folder);
}

/** Does an impl match a free-text rail query (name / id / folder path / tag, case-insensitive)? Mirrors
 *  the components rail's `matchesQuery` (#3589) — the folder path matches too, so a query like
 *  `viz/examples` filters the rail to a folder. Empty query → all. Pure. */
export function matchesImpl(im: AlgoImpl, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return (
    im.name.toLowerCase().includes(q) ||
    im.id.toLowerCase().includes(q) ||
    (im.folder ?? "").toLowerCase().includes(q) ||
    (im.tags ?? []).some((t) => t.toLowerCase().includes(q))
  );
}

// ── The per-kit graph (#2863/#2958) — the kit's OWN graph: nodes are its implementations (a concept IS
// its implementation), wired by `composes` (builds-on, pointing down to the primitive base). Per-language,
// not deduped: each kit renders only its own impls. This is what a kit's center graph draws. ──

/** A per-kit edge relationship — just `composes` now the abstract ontology is gone (#2961). */
export type KitRel = "composes";

/** Per-kit-rel display label + edge style. Shared by the kit-graph canvas AND the on-graph legend (#2909)
 *  so the key never drifts from the drawn edges. */
export const KIT_REL_META: Record<KitRel, { label: string; dashed?: boolean; doubleEnded?: boolean }> = {
  composes: { label: "composes" },
};

/** The order kit-rel legend rows read in. */
export const KIT_REL_ORDER: KitRel[] = ["composes"];

/** An edge in a kit graph — endpoints are implementation ids. */
export interface KitEdge { from: string; to: string; rel: KitRel }

/** A language kit as its own graph: the kit's impls + the `composes` edges between them. */
export interface KitGraph { nodes: AlgoImpl[]; edges: KitEdge[] }

/**
 * Build a kit's own graph (#2863/#2958) from `graph.implementations`, scoped to `tech`: each impl → the
 * same-tech impls it `composes` (the "grows up from the primitive base" edges). The abstract concept
 * ontology is gone (#2961), so `composes` is the only edge. Pure.
 */
export function kitGraph(graph: KnowledgeGraph, tech: Tech): KitGraph {
  const nodes = kitImpls(graph, tech);
  const ids = new Set(nodes.map((n) => n.id));
  const edges: KitEdge[] = [];
  for (const im of nodes) {
    for (const c of im.composes) if (ids.has(c)) edges.push({ from: im.id, to: c, rel: "composes" });
  }
  return { nodes, edges };
}

// ── Layout — the kit graph columns by compose depth (primitives at the base, algorithms deepening right). ──

/** A node's laid-out position (top-left, world coords). */
export interface NodePos { x: number; y: number }

/** A design-space box — matches the viewport's `GraphBox` so it can drive `contentBounds`. */
export interface Box { x: number; y: number; w: number; h: number }

export interface KnowledgeLayout {
  pos: Map<string, NodePos>;
  world: { w: number; h: number };
  /** The bounding box of the actual nodes — framed by `fit()` so the graph centers on content. */
  bounds: Box;
  /** The laid-out cluster boxes, for the canvas to caption. Present so the grouping is VISIBLE: an
   *  unlabelled pack reads as an arbitrary grid, and the whole point is that the region means
   *  something the rail also names. */
  clusters: ClusterBox[];
}

/** Node box size (world px) — shared by the layout and the canvas card. */
export const NODE_W = 172;
export const NODE_H = 58;
const PAD = 48;
/** Cell pitch INSIDE a cluster. Tight: a cluster's members are adjacent, so no edge gutter is owed. */
const CELL_W = NODE_W + 20;
const CELL_H = NODE_H + 16;
const LABEL_H = 26;
const CLUSTER_GAP = 30;
const BAND_GAP = 56;
/**
 * Width the packer wraps clusters at — the ONE tuning knob. Raising it makes the world wider and
 * shorter. MEASURED over the real store at 3800: 3,894 x 6,146 (1.58:1), against 3,308 x 43,114
 * (13:1) before.
 *
 * Deliberately NOT a viewport measurement. The world must be stable for a given graph; a layout that
 * reflowed on window resize would move every node out from under the reader's cursor.
 */
const BAND_W = 3800;
/** Slightly wide clusters read better than square ones at this cell ratio. */
const CLUSTER_ASPECT = 1.9;

/**
 * The bands, in draw order. A node's ORIGIN — where its code actually lives — is the coarse axis, so
 * crate code and frontend code occupy separate regions instead of interleaving. That separation is what
 * the crate migration needs: `crates/*` records are a different population from `src/*` ones, and the
 * reference algorithms (textbook `a-star.rs`, `bfs.rs`) are a third that belongs in neither.
 */
export const ORIGIN_BANDS = [
  "crates", "backend", "features", "shared", "shell", "store", "reference", "built-ins", "other",
] as const;
export type Origin = (typeof ORIGIN_BANDS)[number];

/** Which band a node belongs to. From `src` (94% populated); `role`/absence covers the rest. */
export function originOf(im: AlgoImpl): Origin {
  if (im.role === "primitive") return "built-ins";
  const s = im.src ?? "";
  if (!s) return "reference";
  if (s.startsWith("crates/")) return "crates";
  if (s.startsWith("src-tauri/")) return "backend";
  if (s.startsWith("src/features/")) return "features";
  if (s.startsWith("src/shared/")) return "shared";
  if (s.startsWith("src/app")) return "shell";
  if (s.startsWith("src/store")) return "store";
  return "other";
}

/**
 * The cluster a node sits in inside its band — the CRATE for crate code, the FEATURE for a feature
 * module, else the folder. Chosen because THE RAIL ALREADY NAVIGATES BY FOLDER, so the canvas and the
 * rail finally describe the same structure rather than being two unrelated views of one graph.
 */
export function clusterOf(im: AlgoImpl): string {
  const s = im.src ?? "";
  if (s.startsWith("crates/")) return s.split("/")[1] || "crates";
  if (s.startsWith("src/features/")) return s.split("/")[2] || "features";
  return im.folder || im.domain || "general";
}

/** Rows/cols for `n` cells, aiming at {@link CLUSTER_ASPECT}. */
function gridFor(n: number): { cols: number; rows: number } {
  const cols = Math.max(1, Math.round(Math.sqrt((n * CLUSTER_ASPECT * CELL_H) / CELL_W)));
  return { cols, rows: Math.ceil(n / cols) };
}

/** Per-impl "compose depth": a primitive is the base (0); an algorithm is 1 + the deepest in-kit impl
 *  it composes (min 1). No longer the global X axis — 84% of a real kit shares depth 1, so as a column
 *  key it sorted nothing. It survives as the ORDER WITHIN a cluster, where base-to-derived still reads.
 *  Cycle-guarded (composes shouldn't cycle, but a bad kit won't hang). */
function composeDepth(kit: KitGraph): Map<string, number> {
  const byId = new Map(kit.nodes.map((n) => [n.id, n]));
  const memo = new Map<string, number>();
  const visiting = new Set<string>();
  const depth = (id: string): number => {
    if (memo.has(id)) return memo.get(id)!;
    const node = byId.get(id);
    if (!node || node.role === "primitive") { memo.set(id, 0); return 0; }
    if (visiting.has(id)) return 1; // cycle guard
    visiting.add(id);
    const composed = node.composes.filter((c) => byId.has(c));
    const d = composed.length ? 1 + Math.max(...composed.map(depth)) : 1;
    visiting.delete(id);
    memo.set(id, d);
    return d;
  };
  for (const n of kit.nodes) depth(n.id);
  return memo;
}

/** A laid-out cluster: its caption, its box, and how many nodes it holds. */
export interface ClusterBox {
  origin: Origin;
  label: string;
  x: number;
  y: number;
  w: number;
  h: number;
  count: number;
}

/**
 * Lay a kit graph out as ORIGIN BANDS of FOLDER CLUSTERS, depth-ordered inside each cluster.
 *
 * It replaced a column-per-`composeDepth` stack with NO row wrap, which put 538 of 644 typescript nodes
 * in one column and produced a 3,308 x 43,114 world — 52 screens of vertical travel to reach a node.
 * Wrapping the depths alone was measured too, and merely traded that for 8,280px of width: depth cannot
 * be the organising axis when 84% of a kit shares one value.
 *
 * Pure + deterministic — positions are keyed by impl id and depend only on `kit`, so the same graph lays
 * out identically every time and the same canvas/viewport draw it.
 */
export function layoutKitGraph(kit: KitGraph): KnowledgeLayout {
  const depths = composeDepth(kit);
  const pos = new Map<string, NodePos>();
  const clusters: ClusterBox[] = [];

  const bands = new Map<Origin, Map<string, AlgoImpl[]>>();
  for (const n of kit.nodes) {
    const o = originOf(n);
    const c = clusterOf(n);
    let byCluster = bands.get(o);
    if (!byCluster) {
      byCluster = new Map();
      bands.set(o, byCluster);
    }
    const list = byCluster.get(c);
    if (list) list.push(n);
    else byCluster.set(c, [n]);
  }

  let y = PAD;
  let worldW = 0;
  for (const origin of ORIGIN_BANDS) {
    const byCluster = bands.get(origin);
    if (!byCluster) continue;
    // Largest first: shelf packing wastes least when the tall blocks are placed early. The name
    // tiebreak keeps two equally sized clusters in a stable order run to run.
    const ordered = [...byCluster.entries()].sort(
      (a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]),
    );

    let x = PAD;
    let shelfH = 0;
    const bandTop = y + LABEL_H;
    let bandBottom = bandTop;
    for (const [label, members] of ordered) {
      const { cols } = gridFor(members.length);
      const rows = Math.ceil(members.length / cols);
      const w = cols * CELL_W;
      const h = rows * CELL_H + LABEL_H;
      if (x > PAD && x + w > BAND_W) {
        y = bandBottom + CLUSTER_GAP;
        x = PAD;
        shelfH = 0;
      }
      const top = Math.max(y, bandTop);
      const sorted = [...members].sort(
        (a, b) => (depths.get(a.id) ?? 0) - (depths.get(b.id) ?? 0) || a.name.localeCompare(b.name),
      );
      sorted.forEach((n, i) => {
        pos.set(n.id, { x: x + (i % cols) * CELL_W, y: top + LABEL_H + Math.floor(i / cols) * CELL_H });
      });
      clusters.push({ origin, label, x, y: top, w, h, count: members.length });
      x += w + CLUSTER_GAP;
      shelfH = Math.max(shelfH, h);
      bandBottom = Math.max(bandBottom, top + shelfH);
      worldW = Math.max(worldW, x);
    }
    y = bandBottom + BAND_GAP;
  }

  const world = { w: worldW + PAD, h: Math.max(y - BAND_GAP, PAD) + PAD };
  const bounds: Box = {
    x: PAD,
    y: PAD,
    w: Math.max(world.w - PAD * 2, 0),
    h: Math.max(world.h - PAD * 2, 0),
  };
  return { pos, world, bounds, clusters };
}
